// Snapshot contract tests — schema v2 (D-01 M1-sourcing extension).
//
// The committed fixture is REAL producer output: generated by the
// grave-indexer production serializer (buildConsoleSnapshot), digest-pinned
// in src/lib/gy/snapshot-fixture/PROVENANCE.md. Positive cases pin
// what the serializer emits and that the console consumes it end to end;
// the negative battery proves the fail-closed reader rejects every contract
// violation (missing/unknown keys, v1 payloads, D-01 sourcing deviations,
// counts drift, fabricated criteria) with a deterministic SnapshotError —
// mirroring the indexer's normative reader (src/consoleSnapshotParse.ts,
// grave-indexer PR #4).

/// <reference types="bun-types" />
import { describe, test, expect } from "bun:test";

import {
  parseSnapshot,
  snapshotFreshness,
  snapshotDataState,
  snapshotPools,
  snapshotCriteriaOf,
  poolFromSnapshot,
  SNAPSHOT,
  RAW_SNAPSHOT,
  SnapshotError,
  CANONICAL_WSOL_MINT,
  type ConsoleSnapshot,
} from "../snapshot";

const GENERATED_AT = SNAPSHOT.generatedAtUnixMs;
const MAX_AGE = SNAPSHOT.freshness.maxAgeMs;

/** Deep-clone the committed artifact and mutate it into a malformed shape. */
function corrupt(mutate: (snap: Record<string, unknown>) => void): unknown {
  const copy = JSON.parse(JSON.stringify(RAW_SNAPSHOT)) as Record<string, unknown>;
  mutate(copy);
  return copy;
}

type SnapObj = Record<string, unknown>;

function poolsOf(s: SnapObj): Record<string, unknown>[] {
  return s.pools as Record<string, unknown>[];
}

/** Shape an exact v1 payload (strip the v2 sourcing fields) — proves v1 is never reinterpreted. */
function toV1(s: SnapObj): SnapObj {
  for (const p of poolsOf(s)) {
    delete p.coinMint;
    delete p.pcMint;
    delete p.m1Sourcing;
  }
  delete (s.counts as SnapObj).m1SourcingRejected;
  s.schemaVersion = 1;
  return s;
}

describe("snapshot loader — committed artifact (real serializer output)", () => {
  test("the committed snapshot.json parses as schemaVersion 2 and is internally consistent", () => {
    const snap = SNAPSHOT;
    expect(snap.schemaVersion).toBe(2);
    expect(snap.cluster).toBe("mainnet-beta");
    expect(snap.pools.length).toBe(snap.counts.enriched);
    expect(snap.pools.length).toBeGreaterThan(0);
    // The v2 sourcing total rides in counts and agrees with failures[].
    expect(snap.counts.m1SourcingRejected).toBe(
      snap.failures.filter((f) => f.stage === "m1-sourcing").length,
    );
    expect(snap.counts.m1SourcingRejected).toBeLessThanOrEqual(snap.counts.supportedWsolPairs);
    expect(snap.pools.length).toBeLessThanOrEqual(snap.counts.supportedWsolPairs - snap.counts.m1SourcingRejected);
    // Canonical ordering survives the artifact boundary.
    const addresses = snap.pools.map((p) => p.address);
    expect(addresses).toEqual([...addresses].sort());
    // Honest criteria: nothing is ever pre-evaluated for C2/C4/C5/C6.
    for (const p of snap.pools) {
      expect(p.criteria.c2PriceCollapse).toBe("pending");
      expect(p.criteria.c4LpBurned).toBe("pending");
      expect(p.criteria.c5LpLocked).toBe("pending");
      expect(p.criteria.c6MultiEpoch).toBe("pending");
    }
    // Secret-free by construction.
    const json = JSON.stringify(snap);
    expect(json).not.toContain("http");
  });

  test("every committed pool carries the exact D-01 M1-sourcing acceptance", () => {
    for (const p of SNAPSHOT.pools) {
      // Orientation: WSOL on pc_mint (quote side), non-WSOL on coin_mint.
      expect(p.coinMint).not.toBe(CANONICAL_WSOL_MINT);
      expect(p.pcMint).toBe(CANONICAL_WSOL_MINT);
      expect(p.baseMint).toBe(p.coinMint); // documented builder aliasing
      expect(p.quoteMint).toBe(p.pcMint);
      expect(p.wsolSide.coinIsWsol).toBe(false);
      expect(p.wsolSide.memecoinMint).toBe(p.coinMint);
      // The machine-checkable acceptance, exactly as the producer emits it.
      expect(p.m1Sourcing).toEqual({ eligible: true, wsolSide: "pc_mint", reason: null });
    }
  });

  test("criteria math from the serializer: fixture pool A passes C1+C3, pool B is pending+fail", () => {
    // Pinned by the fixture generator (src/lib/gy/snapshot-fixture/):
    // A — silent 8_000_000 s ≥ 7_776_000 s and reserve 0.6 SOL ≥ 0.5 SOL;
    // B — last swap not derivable (C1 pending) and reserve 0.499999999 SOL (C3 fail).
    expect(SNAPSHOT.pools[0]!.criteria.c1Inactivity).toBe("pass");
    expect(SNAPSHOT.pools[0]!.criteria.c3MinTvl).toBe("pass");
    const b = SNAPSHOT.pools.find((p) => p.lastSwap === null);
    expect(b).toBeDefined();
    expect(b!.criteria.c1Inactivity).toBe("pending");
    expect(b!.criteria.c3MinTvl).toBe("fail");
  });

  test("freshness math honors the artifact's own budget", () => {
    expect(snapshotFreshness(SNAPSHOT, GENERATED_AT + MAX_AGE)).toBe("fresh");
    expect(snapshotFreshness(SNAPSHOT, GENERATED_AT + MAX_AGE + 1)).toBe("stale");
    expect(snapshotDataState(SNAPSHOT, GENERATED_AT + 1)).toBe("real");
    expect(snapshotDataState(SNAPSHOT, GENERATED_AT + MAX_AGE + 1)).toBe("stale");
  });

  test("poolFromSnapshot maps real quantities without fabrication", () => {
    const pool = poolFromSnapshot(SNAPSHOT.pools[0]!, SNAPSHOT);
    expect(pool.address).toBe(SNAPSHOT.pools[0]!.address);
    expect(pool.amm).toBe("Raydium V4");
    expect(pool.quoteSymbol).toBe("WSOL");
    expect(pool.baseSymbol.startsWith("mint:")).toBe(true);
    expect(pool.quoteReserveLamports).toBe(BigInt(SNAPSHOT.pools[0]!.wsolReserveLamports));
    expect(pool.baseReserve).toBe(BigInt(SNAPSHOT.pools[0]!.memecoinReserveRaw));
    expect(pool.baseDecimals).toBe(SNAPSHOT.pools[0]!.memecoinDecimals);
    expect(pool.lpSupply).toBe(Number(BigInt(SNAPSHOT.pools[0]!.lpSupplyRaw)));
    // Truthful lifecycle + score: discovered, never a fabricated score.
    expect(pool.state).toBe("discovered");
    expect(pool.score).toBe(0);
    expect(pool.anchorEpoch).toBeNull();
    expect(pool.certExpiresAt).toBeNull();
    // Criteria honesty rides along (C1/C3 states on the Pool; the full
    // pending-pinned criteria remain on the snapshot record).
    expect(pool.snapshotCriteria!.c1Inactivity).toBe(SNAPSHOT.pools[0]!.criteria.c1Inactivity);
    expect(pool.snapshotCriteria!.c3MinTvl).toBe(SNAPSHOT.pools[0]!.criteria.c3MinTvl);
    expect(SNAPSHOT.pools[0]!.criteria.c4LpBurned).toBe("pending");
    expect(SNAPSHOT.pools[0]!.criteria.c5LpLocked).toBe("pending");
  });

  test("lastSwap unavailable maps to 0 with an explanatory note — never as a real zero", () => {
    const withoutSwap = SNAPSHOT.pools.find((p) => p.lastSwap === null);
    expect(withoutSwap).toBeDefined(); // the fixture carries one by design
    const pool = poolFromSnapshot(withoutSwap!, SNAPSHOT);
    expect(pool.lastSwapUnix).toBe(0);
    expect(pool.note).toContain("unavailable");
  });

  test("snapshotPools preserves the canonical order and the UI criteria rows read the artifact", () => {
    const pools = snapshotPools(SNAPSHOT);
    expect(pools.map((p) => p.address)).toEqual(SNAPSHOT.pools.map((p) => p.address));
    const rows = snapshotCriteriaOf(pools[0]!, Date.now(), SNAPSHOT);
    expect(rows.map((r) => r.id)).toEqual(["C1", "C2", "C3", "C4", "C5", "C6"]);
    expect(rows.find((r) => r.id === "C1")!.state).toBe(SNAPSHOT.pools[0]!.criteria.c1Inactivity);
    expect(rows.find((r) => r.id === "C3")!.state).toBe(SNAPSHOT.pools[0]!.criteria.c3MinTvl);
    for (const id of ["C2", "C4", "C5", "C6"]) {
      expect(rows.find((r) => r.id === id)!.state).toBe("pending");
    }
  });
});

describe("snapshot loader — schema version policy (strict v2-only)", () => {
  test("rejects an exact v1 payload with an actionable error — never reinterpreted as v2", () => {
    const v1 = corrupt(toV1);
    expect(() => parseSnapshot(v1)).toThrow(SnapshotError);
    try {
      parseSnapshot(v1);
      throw new Error("expected SnapshotError");
    } catch (e) {
      expect(e).toBeInstanceOf(SnapshotError);
      expect((e as Error).message).toContain("schemaVersion 1 is not supported");
      expect((e as Error).message).toContain("Regenerate");
    }
  });

  test("rejects missing, string-typed and future schemaVersions", () => {
    expect(() => parseSnapshot(corrupt((s) => { delete s.schemaVersion; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { s.schemaVersion = "2"; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { s.schemaVersion = 3; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { s.schemaVersion = 9; }))).toThrow(SnapshotError);
    try {
      parseSnapshot(corrupt((s) => { s.schemaVersion = 3; }));
      throw new Error("expected SnapshotError");
    } catch (e) {
      expect((e as Error).message).toContain("accepts only schemaVersion 2");
    }
  });

  test("unknown root keys are rejected — no silent field smuggling", () => {
    expect(() => parseSnapshot(corrupt((s) => { s.extraTopLevel = 1; }))).toThrow(SnapshotError);
  });
});

describe("snapshot loader — D-01 sourcing validation (fail-closed)", () => {
  test("missing coinMint / pcMint", () => {
    expect(() => parseSnapshot(corrupt((s) => { delete poolsOf(s)[0]!.coinMint; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { delete poolsOf(s)[0]!.pcMint; }))).toThrow(SnapshotError);
  });

  test("WSOL on coinMint is rejected — the gate only emits WSOL on pc_mint", () => {
    const s = corrupt((snap) => { poolsOf(snap)[0]!.coinMint = CANONICAL_WSOL_MINT; });
    // keep the aliasing consistent so ONLY the orientation rule fires
    const pools = poolsOf(s as SnapObj);
    pools[0]!.baseMint = CANONICAL_WSOL_MINT;
    (pools[0]!.wsolSide as SnapObj).memecoinMint = CANONICAL_WSOL_MINT;
    expect(() => parseSnapshot(s)).toThrow(SnapshotError);
    try {
      parseSnapshot(s);
      throw new Error("expected SnapshotError");
    } catch (e) {
      expect((e as Error).message).toContain("must be non-WSOL");
    }
  });

  test("non-WSOL pcMint is rejected", () => {
    const s = corrupt((snap) => {
      const pools = poolsOf(snap);
      const wrong = "2MNus2KCvYmRtY3PUQCfhNg9MEKZY6aPzTo7mV1frK6Q"; // synthetic non-WSOL base58
      pools[0]!.pcMint = wrong;
      pools[0]!.quoteMint = wrong;
    });
    expect(() => parseSnapshot(s)).toThrow(SnapshotError);
    try {
      parseSnapshot(s);
      throw new Error("expected SnapshotError");
    } catch (e) {
      expect((e as Error).message).toContain("must be the canonical WSOL mint");
    }
  });

  test("baseMint/quoteMint aliasing contradictions are rejected", () => {
    expect(() =>
      parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.baseMint = "8qbHbw2BbhCLjsGmCnZ8sIsY3D3YvAd4t4QyNDgjPgvj"; })),
    ).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.quoteMint = "8qbHbw2BbhCLjsGmCnZ8sIsY3D3YvAd4t4QyNDgjPgvj"; })),
    ).toThrow(SnapshotError);
  });

  test("missing or non-object m1Sourcing is rejected", () => {
    expect(() => parseSnapshot(corrupt((s) => { delete poolsOf(s)[0]!.m1Sourcing; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.m1Sourcing = "pc_mint"; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.m1Sourcing = { eligible: true }; }))).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.m1Sourcing = { eligible: true, wsolSide: "pc_mint", reason: null, extra: 1 }; })),
    ).toThrow(SnapshotError);
  });

  test("wrong eligible / wsolSide / reason are rejected — the acceptance is exact", () => {
    expect(() =>
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.m1Sourcing as SnapObj).eligible = false; })),
    ).toThrow(SnapshotError);
    try {
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.m1Sourcing as SnapObj).eligible = false; }));
      throw new Error("expected SnapshotError");
    } catch (e) {
      expect((e as Error).message).toContain("must be true for every emitted pool");
    }
    expect(() =>
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.m1Sourcing as SnapObj).wsolSide = "coin_mint"; })),
    ).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.m1Sourcing as SnapObj).reason = "wsol-on-coin-side"; })),
    ).toThrow(SnapshotError);
  });

  test("contradictory wsolSide (coinIsWsol true / memecoinMint mismatch) is rejected", () => {
    expect(() =>
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.wsolSide as SnapObj).coinIsWsol = true; })),
    ).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.wsolSide as SnapObj).memecoinMint = "8qbHbw2BbhCLjsGmCnZ8sIsY3D3YvAd4t4QyNDgjPgvj"; })),
    ).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { delete (poolsOf(s)[0]!.wsolSide as SnapObj).coinIsWsol; }))).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.wsolSide as SnapObj).coinIsWsol = "false"; })),
    ).toThrow(SnapshotError);
  });
});

describe("snapshot loader — counts and failures consistency", () => {
  test("missing counts.m1SourcingRejected is rejected", () => {
    expect(() => parseSnapshot(corrupt((s) => { delete (s.counts as SnapObj).m1SourcingRejected; }))).toThrow(SnapshotError);
  });

  test("m1SourcingRejected above the supported-pair cap is rejected", () => {
    const s = corrupt((snap) => {
      const counts = snap.counts as SnapObj;
      counts.m1SourcingRejected = (counts.supportedWsolPairs as number) + 1;
      // Keep the failures↔count equality so ONLY the cap rule fires.
      const failures = snap.failures as SnapObj[];
      failures.length = 0;
      for (let i = 0; i < (counts.m1SourcingRejected as number); i++) {
        failures.push({ stage: "m1-sourcing", pool: `P${i}111111111111111111111111111111111111111`, reason: "x" });
      }
    });
    expect(() => parseSnapshot(s)).toThrow(SnapshotError);
    try {
      parseSnapshot(s);
      throw new Error("expected SnapshotError");
    } catch (e) {
      expect((e as Error).message).toContain("exceeds counts.supportedWsolPairs");
    }
  });

  test("enriched/pool count drift is rejected", () => {
    expect(() =>
      parseSnapshot(corrupt((s) => { (s.counts as SnapObj).enriched = (poolsOf(s).length as number) + 1; })),
    ).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { (s.counts as SnapObj).enriched = (poolsOf(s).length as number) - 1; })),
    ).toThrow(SnapshotError);
  });

  test("a m1-sourcing count without matching failure records is rejected", () => {
    const s = corrupt((snap) => {
      snap.failures = (snap.failures as SnapObj[]).filter((f) => f.stage !== "m1-sourcing");
    });
    expect(() => parseSnapshot(s)).toThrow(SnapshotError);
    try {
      parseSnapshot(s);
      throw new Error("expected SnapshotError");
    } catch (e) {
      expect((e as Error).message).toContain(`!= failures with stage "m1-sourcing"`);
    }
  });

  test("duplicate m1-sourcing failure records are rejected", () => {
    const s = corrupt((snap) => {
      const failures = snap.failures as SnapObj[];
      const dup = failures.find((f) => f.stage === "m1-sourcing")!;
      failures.push(JSON.parse(JSON.stringify(dup)));
      const counts = snap.counts as SnapObj;
      counts.m1SourcingRejected = (counts.m1SourcingRejected as number) + 1;
    });
    expect(() => parseSnapshot(s)).toThrow(SnapshotError);
    try {
      parseSnapshot(s);
      throw new Error("expected SnapshotError");
    } catch (e) {
      expect((e as Error).message).toContain("appears more than once");
    }
  });

  test("a m1-sourcing failure without a pool address is rejected", () => {
    const s = corrupt((snap) => {
      const failures = snap.failures as SnapObj[];
      const idx = failures.findIndex((f) => f.stage === "m1-sourcing");
      delete failures[idx]!.pool;
    });
    expect(() => parseSnapshot(s)).toThrow(SnapshotError);
  });
});

describe("snapshot loader — exhaustive field validation", () => {
  test("unknown keys at every level are rejected", () => {
    expect(() => parseSnapshot(corrupt((s) => { s.unknownRootKey = true; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { (s.provenance as SnapObj).extra = 1; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { (s.freshness as SnapObj).extra = 1; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { (s.counts as SnapObj).extra = 1; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { (s.failures as SnapObj[])[0]!.extra = 1; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { (s.thresholds as SnapObj).extra = 1; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.extra = 1; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.criteria as SnapObj).extra = 1; }))).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.lastSwap as SnapObj).extra = 1; })),
    ).toThrow(SnapshotError);
  });

  test("missing required root/level keys are rejected", () => {
    for (const key of ["generatedAtUnixMs", "cluster", "provenance", "freshness", "counts", "failures", "thresholds", "pools"]) {
      expect(() => parseSnapshot(corrupt((s) => { delete s[key]; }))).toThrow(SnapshotError);
    }
  });

  test("malformed pool identity is rejected", () => {
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.address = "not base58!!"; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.ammProgramId = "0xdeadbeef"; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.address = 12345; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { delete poolsOf(s)[0]!.lpMint; }))).toThrow(SnapshotError);
  });

  test("u64 fields carried as numbers or malformed strings are rejected", () => {
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.wsolReserveLamports = 123; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.lpSupplyRaw = "01"; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.wsolReserveLamports = "18446744073709551616"; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { (s.thresholds as SnapObj).inactivitySeconds = 7776000; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.memecoinDecimals = 256; }))).toThrow(SnapshotError);
  });

  test("fabricated criteria — only pass|fail|pending and pending-only fields", () => {
    expect(() =>
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.criteria as SnapObj).c4LpBurned = "pass"; })),
    ).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.criteria as SnapObj).c1Inactivity = "maybe"; })),
    ).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { (poolsOf(s)[0]!.criteria as SnapObj).c6MultiEpoch = "fail"; })),
    ).toThrow(SnapshotError);
  });

  test("invalid provenance is rejected", () => {
    expect(() =>
      parseSnapshot(corrupt((s) => { (s.provenance as SnapObj).source = "raydium-v6-gpa"; })),
    ).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { (s.provenance as SnapObj).endpointKind = "irc"; })),
    ).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { (s.provenance as SnapObj).ordering = "unsorted"; })),
    ).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => {
        const prov = s.provenance as SnapObj;
        prov.slotLowerBound = 200;
        prov.slotUpperBound = 100;
      })),
    ).toThrow(SnapshotError);
  });

  test("invalid freshness and clusters are rejected", () => {
    expect(() => parseSnapshot(corrupt((s) => { s.freshness = { maxAgeMs: 0 }; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { s.freshness = { maxAgeMs: -5 }; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { s.freshness = {}; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { s.cluster = "mainnet"; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { s.generatedAtUnixMs = 0; }))).toThrow(SnapshotError);
  });

  test("non-object lastSwap shapes and zero timestamps are rejected", () => {
    expect(() =>
      parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.lastSwap = { unixTs: 0, slot: 5, signature: "x".repeat(20) }; })),
    ).toThrow(SnapshotError);
    expect(() =>
      parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.lastSwap = { unixTs: 1_800_000_000, slot: 5 }; })),
    ).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.lastSwap = 42; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { poolsOf(s)[0]!.lastSwap = undefined; }))).toThrow(SnapshotError);
  });

  test("failures must be objects with stage/reason — unknown keys rejected", () => {
    expect(() => parseSnapshot(corrupt((s) => { s.failures = "none"; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { (s.failures as SnapObj[])[0]!.reason = ""; }))).toThrow(SnapshotError);
    expect(() => parseSnapshot(corrupt((s) => { (s.failures as SnapObj[])[0]!.pool = 123; }))).toThrow(SnapshotError);
  });
});

describe("snapshot loader — artifact timestamps are structurally sane", () => {
  test("generatedAt must not be in the future (clock-skew tolerance 5 min)", () => {
    expect(SNAPSHOT.generatedAtUnixMs).toBeLessThanOrEqual(Date.now() + 5 * 60_000);
  });

  test("the refresh policy default is 24 h — a different budget is a deliberate contract change", () => {
    expect(MAX_AGE).toBe(24 * 3_600_000);
  });

  test("per-pool fetch times must not postdate the artifact generation", () => {
    for (const p of SNAPSHOT.pools) {
      expect(p.fetchedAtUnixMs).toBeLessThanOrEqual(SNAPSHOT.generatedAtUnixMs + 60_000);
    }
  });
});
